package com.fintaxpro;
import java.time.*;import java.util.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.oauth2.jwt.*;import org.springframework.security.oauth2.jose.jws.MacAlgorithm;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/auth") public class AuthController{
 final UserRepository users;final WorkspaceRepository spaces;final PasswordEncoder passwords;final JwtEncoder jwt;final boolean secure;
 AuthController(UserRepository u,WorkspaceRepository w,PasswordEncoder p,JwtEncoder j,@Value("${fintax.cookie-secure}")boolean secure){users=u;spaces=w;passwords=p;jwt=j;this.secure=secure;}
 record Registration(@NotBlank @Size(max=80)String name,@Email @NotBlank @Size(max=254)String email,@NotBlank @Size(min=10,max=72)String password){}
 record Login(@Email @NotBlank String email,@NotBlank @Size(max=72)String password){}
 @PostMapping("/register") @Transactional ResponseEntity<?> register(@Valid @RequestBody Registration r){String email=r.email.toLowerCase(Locale.ROOT).trim();if(users.findByEmail(email).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Account already exists.");AppUser u=users.save(new AppUser(UUID.randomUUID().toString(),email,r.name.trim(),passwords.encode(r.password)));spaces.save(new WorkspaceRecord(u.id));return session(u);}
 @PostMapping("/login") ResponseEntity<?> login(@Valid @RequestBody Login r){AppUser u=users.findByEmail(r.email.toLowerCase(Locale.ROOT).trim()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password."));if(!passwords.matches(r.password,u.passwordHash))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password.");return session(u);}
 ResponseEntity<?> session(AppUser u){Instant now=Instant.now();String token=jwt.encode(JwtEncoderParameters.from(JwsHeader.with(MacAlgorithm.HS256).build(),JwtClaimsSet.builder().issuer("fintaxpro").subject(u.id).issuedAt(now).expiresAt(now.plusSeconds(3600)).build())).getTokenValue();return ResponseEntity.ok().header(HttpHeaders.SET_COOKIE,ResponseCookie.from("fintax_session",token).httpOnly(true).secure(secure).sameSite("Strict").path("/").maxAge(Duration.ofHours(1)).build().toString()).body(Map.of("name",u.name,"email",u.email));}
 @PostMapping("/logout") ResponseEntity<?> logout(){return ResponseEntity.ok().header(HttpHeaders.SET_COOKIE,ResponseCookie.from("fintax_session","").httpOnly(true).secure(secure).sameSite("Strict").path("/").maxAge(0).build().toString()).body(Map.of("ok",true));}
}
